<?php
require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/csrf.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT l.*,u.name seller_name,u.created_at seller_since,(SELECT COALESCE(AVG(rating),0) FROM reviews WHERE reviewed_user_id=u.id) seller_rating,(SELECT image_path FROM listing_images WHERE listing_id=l.id ORDER BY id LIMIT 1) image_path FROM listings l JOIN users u ON u.id=l.user_id WHERE l.id=? LIMIT 1");$s->execute([$id]);$l=$s->fetch();if(!$l){http_response_code(404);exit('Listing not found.');}$imgs=db()->prepare('SELECT * FROM listing_images WHERE listing_id=? ORDER BY id');$imgs->execute([$id]);$images=$imgs->fetchAll();$user=current_user();$isAdmin=$user&&$user['role']==='admin';$canSee=$l['status']==='approved'||($user&&((int)$user['id']===(int)$l['user_id']||$isAdmin));if(!$canSee){http_response_code(404);exit('Listing not available.');}
$pred=null;if($isAdmin){$p=db()->prepare('SELECT * FROM fraud_predictions WHERE listing_id=? ORDER BY id DESC LIMIT 1');$p->execute([$id]);$pred=$p->fetch();}
$pageTitle=$l['title'];include __DIR__.'/includes/header.php';?><div class="detail"><div><img class="gallery-main" src="<?=e($images ? $images[0]['image_path'] : listing_visual($l))?>" alt="<?=e($l['title'])?>"><div class="card card-body" style="margin-top:18px"><h3>Description</h3><p style="line-height:1.7"><?=nl2br(e($l['description']))?></p></div></div><aside class="detail-panel"><span class="badge <?=e(trust_class($l['trust_status']??''))?>"><?=e(trust_label($l['trust_status']??''))?></span><h1><?=e($l['title'])?></h1><div class="price" style="font-size:32px"><?=money($l['price'])?></div><div class="stack" style="margin-top:18px"><div><strong>Condition</strong><br><span class="muted"><?=e($l['item_condition'])?></span></div><div><strong>Brand</strong><br><span class="muted"><?=e($l['brand'] ?: 'Not specified')?></span></div><div><strong>Location</strong><br><span class="muted"><?=e($l['location'])?></span></div><div><strong>Seller</strong><br><span class="muted"><?=e($l['seller_name'])?> · <?=number_format((float)$l['seller_rating'],1)?>/5</span></div></div><?php if($user&&(int)$user['id']!==(int)$l['user_id']):?><div class="actions"><form method="post" action="/api/chat.php"><?=csrf_field()?><input type="hidden" name="action" value="start"><input type="hidden" name="listing_id" value="<?=$id?>"><button class="btn">Chat with seller</button></form><form method="post" action="/api/trade.php"><?=csrf_field()?><input type="hidden" name="action" value="request"><input type="hidden" name="listing_id" value="<?=$id?>"><button class="btn btn-light">Send trade request</button></form><a class="btn btn-light" href="/report.php?listing_id=<?=$id?>">Report</a></div><?php elseif(!$user):?><div class="actions"><a class="btn" href="/login.php">Login to chat or trade</a></div><?php endif;?></aside></div><?php if($isAdmin&&$pred):?><div class="card card-body" style="margin-top:28px"><h2>RADIUS TRUST ANALYSIS</h2><div class="price"><?=e($pred['fraud_score'])?> / 100</div><?php foreach(['image_score'=>'Image Similarity','price_score'=>'Price Anomaly','seller_score'=>'Seller Risk','text_score'=>'Text Risk','policy_score'=>'Policy Risk'] as $k=>$label):?><div class="risk-row"><span><?=$label?></span><div class="bar"><i style="width:<?=min(100,(float)$pred[$k])?>%"></i></div><strong><?=round((float)$pred[$k])?></strong></div><?php endforeach;?><h3>Why was this flagged?</h3><p><?=e($pred['explanation'])?></p><div class="actions"><form method="post" action="/api/fraud.php"><?=csrf_field()?><input type="hidden" name="listing_id" value="<?=$id?>"><button class="btn" name="action" value="approve">Approve</button><button class="btn btn-danger" name="action" value="remove">Remove</button><button class="btn btn-light" name="action" value="retry">Retry Analysis</button></form></div></div><?php endif;?><?php include __DIR__.'/includes/footer.php';?>